"""Float rows of the frieze generated by one quiddity cycle given as lists of subgon sizes.
usage: frieze_one.py ROWS '3,4;3;3,3;3,4'   (each ';' entry is the multiset A_i)"""
import sys, math, json
ROWS = int(sys.argv[1]); As = [[int(x) for x in a.split(',')] for a in sys.argv[2].split(';')]
q = [sum(2 * math.cos(math.pi / p) for p in a) for a in As]; n = len(q)
prev = [0.0] * n; cur = [1.0] * n; out = []
for k in range(2, ROWS + 2):
    nxt = [q[(i + k - 1) % n] * cur[i] - prev[i] for i in range(n)]
    out.append((k, [round(x, 6) for x in nxt]))
    if all(abs(x) < 1e-9 for x in nxt) or any(x < -1e-9 for x in nxt): break
    prev, cur = cur, nxt
a, b, c, d = 1.0, 0.0, 0.0, 1.0
for x in q: a, b, c, d = a * x + b, -a, c * x + d, -c
print(json.dumps(dict(A=As, quiddity=[round(x, 6) for x in q], trace=round(a + d, 6), rows=out)))
